def _infer_regime(ctx: dict) -> str | None:
    """简单 regime 标签：基于股票指数涨跌 + 5 日波动。"""
    stock = ctx.get("stock") or {}
    pct = stock.get("index_pct_pct")
    vol = stock.get("index_volatility_5d")
    if pct is None or vol is None:
        return None
    if vol > 0.30:
        return "high_vol"
    if pct > 0.5:
        return "trend_up"
    if pct < -0.5:
        return "trend_down"
    return "range_bound"

def _bucket_vol(vol: float | None) -> str:
    if vol is None:
        return "unknown"
    if vol >= 30:
        return "high"
    if vol >= 18:
        return "medium"
    return "low"

